function bindUI() {
  const provider = document.getElementById("provider_select");
  const model = document.getElementById("model_select");
  const custom = document.getElementById("custom_model_input");
  const gk = document.getElementById("gemini_key_input");
  const rk = document.getElementById("groq_key_input");
  const ok = document.getElementById("openrouter_key_input");

  if (provider) {
    provider.onchange = () => {
      updateProviderUI();
      saveSettings();
    };
  }

  if (model) model.onchange = saveSettings;
  if (custom) custom.oninput = saveSettings;
  if (gk) gk.oninput = saveSettings;
  if (rk) rk.oninput = saveSettings;
  if (ok) ok.oninput = saveSettings;

  const quickBtn = document.getElementById("quick_group_btn");
  const voiceBtn = document.getElementById("voice_button");
  const runBtn = document.getElementById("run_button");
  const clearBtn = document.getElementById("clear_button");

  if (quickBtn) quickBtn.onclick = runQuickGroupBy;
  if (voiceBtn) voiceBtn.onclick = startVoice;
  if (runBtn) runBtn.onclick = executeCommand;
  if (clearBtn) clearBtn.onclick = clearAll;
}

function showStatus(msg, type) {
  const el = document.getElementById("status_area");
  if (!el) return;
  el.className = "status " + type;
  el.innerText = String(msg || "");
}

function foldText(s) {
  return String(s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D");
}

function loadSettings() {
  const provider = document.getElementById("provider_select");
  if (provider) provider.value = localStorage.getItem("exai_provider") || "auto";

  const gk = document.getElementById("gemini_key_input");
  const rk = document.getElementById("groq_key_input");
  const ok = document.getElementById("openrouter_key_input");
  const custom = document.getElementById("custom_model_input");

  if (gk) gk.value = localStorage.getItem(PROVIDERS.gemini.storageKey) || "";
  if (rk) rk.value = localStorage.getItem(PROVIDERS.groq.storageKey) || "";
  if (ok) ok.value = localStorage.getItem(PROVIDERS.openrouter.storageKey) || "";
  if (custom) custom.value = localStorage.getItem("exai_custom_model") || "";

  updateProviderUI();

  const savedModel = localStorage.getItem("exai_model");
  const modelSelect = document.getElementById("model_select");

  if (savedModel && modelSelect && !modelSelect.disabled) {
    for (let i = 0; i < modelSelect.options.length; i++) {
      if (modelSelect.options[i].value === savedModel) {
        modelSelect.value = savedModel;
        break;
      }
    }
  }
}

function saveSettings() {
  const provider = document.getElementById("provider_select");
  const model = document.getElementById("model_select");
  const custom = document.getElementById("custom_model_input");

  if (provider) localStorage.setItem("exai_provider", provider.value);
  if (model) localStorage.setItem("exai_model", model.value);
  if (custom) localStorage.setItem("exai_custom_model", custom.value.trim());

  localStorage.setItem(PROVIDERS.gemini.storageKey, document.getElementById("gemini_key_input")?.value.trim() || "");
  localStorage.setItem(PROVIDERS.groq.storageKey, document.getElementById("groq_key_input")?.value.trim() || "");
  localStorage.setItem(PROVIDERS.openrouter.storageKey, document.getElementById("openrouter_key_input")?.value.trim() || "");
}

function updateProviderUI() {
  const provider = document.getElementById("provider_select")?.value || "auto";

  const geminiBox = document.getElementById("gemini_key_box");
  const groqBox = document.getElementById("groq_key_box");
  const openrouterBox = document.getElementById("openrouter_key_box");

  if (geminiBox) geminiBox.style.display = provider === "auto" || provider === "gemini" ? "block" : "none";
  if (groqBox) groqBox.style.display = provider === "auto" || provider === "groq" ? "block" : "none";
  if (openrouterBox) openrouterBox.style.display = provider === "auto" || provider === "openrouter" ? "block" : "none";

  const modelSelect = document.getElementById("model_select");
  if (!modelSelect) return;

  modelSelect.innerHTML = "";

  if (provider === "auto") {
    const opt = document.createElement("option");
    opt.value = "auto";
    opt.textContent = "Auto - Gemini 3.5 Flash Lite -> Groq -> OpenRouter";
    modelSelect.appendChild(opt);
    modelSelect.disabled = true;
    return;
  }

  modelSelect.disabled = false;

  for (const item of PROVIDERS[provider].models) {
    const opt = document.createElement("option");
    opt.value = item[0];
    opt.textContent = item[1];
    modelSelect.appendChild(opt);
  }

  modelSelect.value = PROVIDERS[provider].defaultModel;
}

function getKey(provider) {
  if (provider === "gemini") return document.getElementById("gemini_key_input")?.value.trim() || "";
  if (provider === "groq") return document.getElementById("groq_key_input")?.value.trim() || "";
  if (provider === "openrouter") return document.getElementById("openrouter_key_input")?.value.trim() || "";
  return "";
}

async function getCandidateModels(provider, apiKey) {
  const selectedProvider = document.getElementById("provider_select")?.value || "auto";
  const custom = document.getElementById("custom_model_input")?.value.trim() || "";
  const modelSelect = document.getElementById("model_select");

  let result = [];

  if (custom && selectedProvider === provider) result.push(custom);

  if (selectedProvider === provider && modelSelect && modelSelect.value !== "auto") {
    result.push(modelSelect.value);
  }

  result.push(PROVIDERS[provider].defaultModel);
  result = result.concat(PROVIDERS[provider].models.map((m) => m[0]));

  if (provider === "gemini") {
    result = result.concat(await fetchGeminiModels(apiKey).catch(() => []));
  }

  if (provider === "groq") {
    result = result.concat(await fetchGroqModels(apiKey).catch(() => []));
  }

  if (provider === "openrouter") {
    result = result.concat(await fetchOpenRouterFreeModels().catch(() => []));
  }

  result = [...new Set(result.filter(Boolean))];

  result = result.filter((m) => {
    if (m.includes("gemini-2.0-flash")) return false;
    if (m.includes("llama-3.1-8b-instant")) return false;
    if (m.includes("deepseek/deepseek-chat-v3-0324")) return false;
    return true;
  });

  return result;
}

async function fetchGeminiModels(apiKey) {
  const res = await fetch("https://generativelanguage.googleapis.com/v1beta/models?key=" + encodeURIComponent(apiKey));
  if (!res.ok) return [];

  const data = await res.json();
  const ids = (data.models || [])
    .filter((m) => (m.supportedGenerationMethods || []).includes("generateContent"))
    .map((m) => String(m.name || "").replace(/^models\//, ""))
    .filter((id) => id.includes("gemini"));

  const preferred = ["gemini-3.5-flash-lite", "gemini-3.5-flash", "gemini-3.6-flash", "gemini-3.6-flash-lite"];
  return [...new Set(preferred.filter((x) => ids.includes(x)).concat(ids))];
}

async function fetchGroqModels(apiKey) {
  const res = await fetch("https://api.groq.com/openai/v1/models", {
    headers: { Authorization: "Bearer " + apiKey }
  });

  if (!res.ok) return [];

  const data = await res.json();
  return (data.data || [])
    .map((m) => m.id)
    .filter(Boolean)
    .filter((id) => !id.includes("llama-3.1-8b-instant"));
}

async function fetchOpenRouterFreeModels() {
  const res = await fetch("https://openrouter.ai/api/v1/models");
  if (!res.ok) return [];

  const data = await res.json();

  const ids = (data.data || [])
    .filter((m) => {
      const p = m.pricing || {};
      return String(p.prompt ?? "") === "0" && String(p.completion ?? "") === "0";
    })
    .map((m) => m.id)
    .filter(Boolean)
    .filter((id) => !id.includes("deepseek/deepseek-chat-v3-0324"));

  const preferred = [
    "qwen/qwen3-coder:free",
    "deepseek/deepseek-r1:free",
    "meta-llama/llama-3.3-70b-instruct:free",
    "mistralai/mistral-7b-instruct:free",
    "google/gemma-3-27b-it:free"
  ];

  return [...new Set(preferred.filter((x) => ids.includes(x)).concat(ids))];
}

async function callAI(prompt, options = {}) {
  const selectedProvider = document.getElementById("provider_select")?.value || "auto";

  if (selectedProvider === "auto") {
    const order = ["gemini", "groq", "openrouter"];
    const errors = [];

    for (const provider of order) {
      const key = getKey(provider);
      if (!key) continue;

      try {
        showStatus("Calling " + PROVIDERS[provider].label + "...", "loading");
        return await callProvider(provider, key, prompt, options);
      } catch (e) {
        errors.push(PROVIDERS[provider].label + ": " + e.message);
        console.warn(provider + " error:", e);
      }
    }

    if (!errors.length) throw new Error("No API key found. Enter Gemini, Groq or OpenRouter key.");
    throw new Error("All providers failed:\n\n" + errors.join("\n\n"));
  }

  const key = getKey(selectedProvider);
  if (!key) throw new Error("Missing API key for " + PROVIDERS[selectedProvider].label);

  return await callProvider(selectedProvider, key, prompt, options);
}

async function callProvider(provider, apiKey, prompt, options = {}) {
  const models = await getCandidateModels(provider, apiKey);
  const errors = [];

  for (const model of models) {
    try {
      showStatus("Calling " + PROVIDERS[provider].label + ": " + model, "loading");

      if (provider === "gemini") {
        return await callGemini(apiKey, model, prompt, options);
      }

      if (provider === "groq") {
        return await callOpenAICompatible(
          "https://api.groq.com/openai/v1/chat/completions",
          provider,
          apiKey,
          model,
          prompt,
          options
        );
      }

      if (provider === "openrouter") {
        return await callOpenAICompatible(
          "https://openrouter.ai/api/v1/chat/completions",
          provider,
          apiKey,
          model,
          prompt,
          options
        );
      }
    } catch (e) {
      errors.push(model + ": " + e.message);
      console.warn(provider + " model " + model + " error:", e);
    }
  }

  throw new Error(PROVIDERS[provider].label + " failed all models:\n" + errors.join("\n"));
}

async function callGemini(apiKey, model, prompt, options = {}) {
  const system = options.system || "You are a helpful AI assistant for Excel, Word and Office.js. Answer in Vietnamese if the user uses Vietnamese.";
  const fullPrompt = system + "\n\n" + prompt;

  const res = await fetch(
    "https://generativelanguage.googleapis.com/v1beta/models/" + encodeURIComponent(model) + ":generateContent?key=" + encodeURIComponent(apiKey),
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
        generationConfig: {
          temperature: options.temperature ?? 0.2,
          maxOutputTokens: options.maxTokens || 8192,
          topP: 0.9
        }
      })
    }
  );

  const data = await res.json().catch(() => ({}));

  if (!res.ok) throw new Error(data.error?.message || "Gemini HTTP " + res.status);

  const text = (data.candidates?.[0]?.content?.parts || [])
    .map((p) => p.text || "")
    .join("")
    .trim();

  if (!text) throw new Error("Gemini returned empty text.");
  return text;
}

async function callOpenAICompatible(apiUrl, provider, apiKey, model, prompt, options = {}) {
  const system = options.system || "You are a helpful AI assistant for Excel, Word and Office.js. Answer in Vietnamese if the user uses Vietnamese.";

  const headers = {
    "Content-Type": "application/json",
    Authorization: "Bearer " + apiKey
  };

  if (provider === "openrouter") {
    headers["HTTP-Referer"] = "https://duongdinhdbp.github.io/EXAI/";
    headers["X-Title"] = "EXAI Free AI";
  }

  const res = await fetch(apiUrl, {
    method: "POST",
    headers,
    body: JSON.stringify({
      model,
      messages: [
        { role: "system", content: system },
        { role: "user", content: prompt }
      ],
      temperature: options.temperature ?? 0.2,
      max_tokens: options.maxTokens || 8192
    })
  });

  const data = await res.json().catch(() => ({}));

  if (!res.ok) {
    throw new Error(data.error?.message || data.message || PROVIDERS[provider].label + " HTTP " + res.status);
  }

  const text = data.choices?.[0]?.message?.content;
  if (!text) throw new Error(PROVIDERS[provider].label + " returned empty text.");

  return text.trim();
}

function cleanCode(code) {
  if (!code) return "";

  code = code
    .replace(/```javascript/gi, "")
    .replace(/```js/gi, "")
    .replace(/```/g, "")
    .trim();

  code = code.replace(/^[\s\S]*?await\s+(Excel|Word)\.run\s*\(\s*async\s*\([^)]*\)\s*=>\s*\{/i, "");
  code = code.replace(/await\s+context\.sync\(\)\s*;?\s*\}\s*\)\s*;?\s*$/i, "");

  return code.trim();
}

function colToLetter(n) {
  let s = "";
  n = n + 1;
  while (n > 0) {
    const m = (n - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

function colToIndex(col) {
  let n = 0;
  const s = String(col || "").toUpperCase().replace(/[^A-Z]/g, "");
  for (let i = 0; i < s.length; i++) n = n * 26 + (s.charCodeAt(i) - 64);
  return n - 1;
}

function parseNumber(v) {
  if (v === null || v === undefined || v === "") return 0;
  if (typeof v === "number") return v;

  let s = String(v).trim().replace(/\s/g, "");
  if (!s) return 0;

  if (s.includes(".") && s.includes(",")) s = s.replace(/\./g, "").replace(",", ".");
  else s = s.replace(",", ".");

  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}

function parseGroupByCommand(text) {
  const raw = String(text || "").trim();
  const folded = foldText(raw).toLowerCase();
  const formulaMode = /cong\s*thuc|formula|ct\b/.test(folded);

  let m = raw.match(/\bgb\s+([A-Z]{1,3}(?:\s*,\s*[A-Z]{1,3})*)\s+([A-Z]{1,3})\s+([A-Z]{1,3}\d{1,7})\b/i);
  if (m) {
    return {
      groupCols: m[1].split(",").map((x) => x.trim().toUpperCase()).filter(Boolean),
      sumCol: m[2].toUpperCase(),
      targetCell: m[3].toUpperCase(),
      formulaMode
    };
  }

  m = raw.match(/\b(?:groupby|pivot|unique_sum)\s*\(\s*([A-Z]{1,3}(?:\s*,\s*[A-Z]{1,3})*)\s*;\s*([A-Z]{1,3})\s*(?:;\s*(?:sum|tong))?\s*;\s*([A-Z]{1,3}\d{1,7})\s*\)/i);
  if (m) {
    return {
      groupCols: m[1].split(",").map((x) => x.trim().toUpperCase()).filter(Boolean),
      sumCol: m[2].toUpperCase(),
      targetCell: m[3].toUpperCase(),
      formulaMode
    };
  }

  const hasGroup = /loc\s*trung|khong\s*trung|unique|gop|gom|nhom|group|pivot/.test(folded);
  const hasSum = /tong|sum|cong|khoi\s*luong/.test(folded);
  if (!hasGroup || !hasSum) return null;

  const target = raw.match(/\b(?:vào|vao|ghi\s+vào|ghi\s+vao|điền\s+vào|dien\s+vao|tại|tai|ô|o)\s*([A-Z]{1,3}\d{1,7})\b/i);
  if (!target) return null;

  let sumCol = null;
  const foldedNoCells = folded.replace(/\b[a-z]{1,3}\d{1,7}\b/gi, " ");

  const sumPatterns = [
    /(?:tong|sum)[\s\S]{0,50}?(?:cot|column)\s*([a-z]{1,3})\b/i,
    /(?:khoi\s*luong)[\s\S]{0,100}?(?:cot|column)\s*([a-z]{1,3})\b/i,
    /(?:la)\s*(?:cot|column)\s*([a-z]{1,3})\b/i
  ];

  for (const p of sumPatterns) {
    const sm = foldedNoCells.match(p);
    if (sm && sm[1]) sumCol = sm[1].toUpperCase();
  }

  const cols = [];
  function addCol(c) {
    c = String(c || "").toUpperCase();
    if (!/^[A-Z]{1,3}$/.test(c)) return;
    if (!cols.includes(c)) cols.push(c);
  }

  for (const cm of foldedNoCells.matchAll(/\b(?:cot|column)\s*([a-z]{1,3})\b/gi)) addCol(cm[1]);
  for (const cm of foldedNoCells.matchAll(/\b(?:va|,|&|\+)\s*([a-z]{1,3})\b/gi)) addCol(cm[1]);

  if (!sumCol && cols.length >= 2) sumCol = cols[cols.length - 1];
  if (!sumCol) return null;

  const groupCols = cols.filter((c) => c !== sumCol);
  if (!groupCols.length) return null;

  return {
    groupCols,
    sumCol,
    targetCell: target[1].toUpperCase(),
    formulaMode
  };
}

function makeGroupByFormula(groupCols, sumCol, startRow, endRow) {
  const groupRanges = groupCols.map((c) => "$" + c + "$" + startRow + ":$" + c + "$" + endRow);
  const sumRange = "$" + sumCol + "$" + startRow + ":$" + sumCol + "$" + endRow;

  const condition = groupCols
    .map((c, idx) => "($" + c + "$" + startRow + ":$" + c + "$" + endRow + "=INDEX(_r,1," + (idx + 1) + "))")
    .join("*");

  const headers = groupCols.map((c) => '"' + c + '"').concat(['"Tong ' + sumCol + '"']).join(",");

  return (
    "=LET(_s," + sumRange +
    ",_g,HSTACK(" + groupRanges.join(",") + ")" +
    ",_u,UNIQUE(_g)" +
    ",VSTACK({" + headers + "},HSTACK(_u,BYROW(_u,LAMBDA(_r,SUM(FILTER(_s," + condition + ")))))))"
  );
}

async function runGroupBy(groupCols, sumCol, targetCell, formulaMode) {
  groupCols = Array.isArray(groupCols)
    ? groupCols.map((x) => String(x).trim().toUpperCase()).filter(Boolean)
    : String(groupCols || "").split(",").map((x) => x.trim().toUpperCase()).filter(Boolean);

  sumCol = String(sumCol || "").trim().toUpperCase();
  targetCell = String(targetCell || "").trim().toUpperCase();

  if (!groupCols.length) throw new Error("Missing group columns. Example: K,G");
  if (!/^[A-Z]{1,3}$/.test(sumCol)) throw new Error("Invalid sum column. Example: F");
  if (!/^[A-Z]{1,3}\d{1,7}$/.test(targetCell)) throw new Error("Invalid target cell. Example: O163");

  await Excel.run(async (context) => {
    const wb = context.workbook;
    const sheet = wb.worksheets.getActiveWorksheet();
    const sel = wb.getSelectedRange();

    sel.load("address, values, rowCount, columnCount, columnIndex, rowIndex");
    await context.sync();

    const startAbsCol = sel.columnIndex;
    const endAbsCol = sel.columnIndex + sel.columnCount - 1;
    const startRow = sel.rowIndex + 1;
    const endRow = sel.rowIndex + sel.rowCount;

    function rel(col) {
      const abs = colToIndex(col);
      if (abs < startAbsCol || abs > endAbsCol) {
        throw new Error(
          "Column " + col + " is not inside selected range " + sel.address +
          ". Please select a range containing " + groupCols.join(", ") + " and " + sumCol + "."
        );
      }
      return abs - startAbsCol;
    }

    const groupIdx = groupCols.map(rel);
    const sumIdx = rel(sumCol);

    if (formulaMode) {
      const formula = makeGroupByFormula(groupCols, sumCol, startRow, endRow);
      sheet.getRange(targetCell).formulas = [[formula]];
      await context.sync();

      showStatus(
        "OK: GroupBy formula written.\n" +
        "Source: " + sel.address + "\n" +
        "Group: " + groupCols.join(", ") + "\n" +
        "Sum: " + sumCol + "\n" +
        "Target: " + targetCell,
        "success"
      );
      return;
    }

    const data = sel.values;
    const map = {};
    const order = [];

    for (let i = 0; i < data.length; i++) {
      const row = data[i];

      const groups = groupIdx.map((idx) => {
        const v = row[idx];
        return v === null || v === undefined ? "" : String(v).trim();
      });

      if (groups.every((x) => x === "")) continue;

      const key = groups.join("\u001f");

      if (!map[key]) {
        map[key] = { groups, sum: 0 };
        order.push(key);
      }

      map[key].sum += parseNumber(row[sumIdx]);
    }

    const output = [
      [...groupCols, "Tong " + sumCol],
      ...order.map((k) => [...map[k].groups, map[k].sum])
    ];

    if (output.length <= 1) throw new Error("No data to group.");

    const target = sheet.getRange(targetCell);
    const outRange = target.getResizedRange(output.length - 1, output[0].length - 1);
    outRange.values = output;
    outRange.format.autofitColumns();

    const header = target.getResizedRange(0, output[0].length - 1);
    header.format.font.bold = true;
    header.format.fill.color = "#D9EAF7";

    await context.sync();

    showStatus(
      "OK: GroupBy done without AI.\n" +
      "Source: " + sel.address + "\n" +
      "Group: " + groupCols.join(", ") + "\n" +
      "Sum: " + sumCol + "\n" +
      "Target: " + targetCell + "\n" +
      "Groups: " + (output.length - 1),
      "success"
    );
  });
}

async function runQuickGroupBy() {
  try {
    const g = document.getElementById("quick_group_cols")?.value || "";
    const s = document.getElementById("quick_sum_col")?.value || "";
    const t = document.getElementById("quick_target_cell")?.value || "";
    await runGroupBy(g, s, t, false);
  } catch (e) {
    console.error(e);
    showStatus("ERROR: " + e.message, "error");
  }
}

function startVoice() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

  if (!SpeechRecognition) {
    showStatus("Voice recognition is not supported in this Excel WebView.", "error");
    return;
  }

  const rec = new SpeechRecognition();
  rec.lang = "vi-VN";
  rec.continuous = false;
  rec.interimResults = false;

  showStatus("Listening...", "loading");

  rec.onresult = (event) => {
    const text = event.results[0][0].transcript || "";
    const input = document.getElementById("prompt_input");
    if (input) input.value = text;
    showStatus("Voice command captured:\n" + text, "success");
  };

  rec.onerror = (event) => {
    showStatus("Voice error: " + event.error, "error");
  };

  rec.start();
}

async function classifyIntent(userPrompt) {
  const f = foldText(userPrompt).toLowerCase();

  const actionRegex =
    /(tinh|cong|tru|nhan|chia|tong|sum|loc|filter|sap xep|sort|to mau|doi mau|dinh dang|format|doi font|xoa|delete|chen|insert|ghi vao|dien vao|copy|sao chep|gop|pivot|dem|count|thay the|replace|sua doan|dich doan|viet.*vao|dua.*vao|tao bang|ke bang)/i;

  const chatRegex =
    /(giai thich|la gi|tai sao|vi sao|huong dan|tu van|cho biet|ke|phan tich giup|noi ve)/i;

  if (actionRegex.test(f) && !chatRegex.test(f)) return "ACTION";

  const prompt =
    "Classify this request. Return exactly one word: CHAT or ACTION.\n\n" +
    "ACTION means changing Excel/Word content, formula, formatting, sorting, filtering or writing content into the file.\n" +
    "CHAT means answering or explaining without changing the file.\n\n" +
    "Request:\n" + userPrompt;

  const result = await callAI(prompt, {
    temperature: 0,
    maxTokens: 20,
    system: "You are an intent classifier. Return only CHAT or ACTION."
  });

  return result.toUpperCase().includes("ACTION") ? "ACTION" : "CHAT";
}

async function handleChat(userPrompt) {
  const cellMatch = userPrompt.match(/\b(?:vào|vao|ghi\s+vào|ghi\s+vao|điền\s+vào|dien\s+vao|trả\s+lời\s+vào|tra\s+loi\s+vao|ô|o)\s*([A-Z]{1,3}\d{1,7})\b/i);
  const targetCell = cellMatch ? cellMatch[1].toUpperCase() : null;

  const chatPrompt =
    "Answer clearly and helpfully in Vietnamese.\n" +
    (targetCell ? "Keep the answer short because it will be written into one Excel cell.\n" : "") +
    "\nUser request:\n" + userPrompt;

  const answer = await callAI(chatPrompt, { temperature: 0.3 });

  if (targetCell && HOST_APP === "Excel") {
    await Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();
      sheet.getRange(targetCell).values = [[answer]];
      await context.sync();
    });

    showStatus("OK: Answer written to " + targetCell + ":\n\n" + answer, "success");
  } else {
    showStatus(answer, "success");
  }
}

async function getExcelContext() {
  let info = "";

  await Excel.run(async (ctx) => {
    const sel = ctx.workbook.getSelectedRange();
    sel.load("address, rowCount, columnCount, values, columnIndex, rowIndex");

    const sheet = ctx.workbook.worksheets.getActiveWorksheet();
    sheet.load("name");

    await ctx.sync();

    const isMulti = sel.rowCount > 1 || sel.columnCount > 1;
    const selAddr = sel.address.split("!").pop();

    info += "- Sheet: " + sheet.name + "\n";

    if (isMulti) {
      info += "\n### SELECTED RANGE: " + selAddr + "\n";
      info += "### Selected data is available as selData.\n";
      info += "- Size: " + sel.rowCount + " rows x " + sel.columnCount + " columns\n";
      info += "- Column mapping:\n";

      for (let j = 0; j < sel.columnCount; j++) {
        info += "  selData[i][" + j + "] = column " + colToLetter(sel.columnIndex + j) + "\n";
      }

      const preview = sel.values
        .slice(0, 25)
        .map((r, i) => "  selData[" + i + "] = [" + r.join(" | ") + "]")
        .join("\n");

      info += "- Preview:\n" + preview + "\n";
      if (sel.rowCount > 25) info += "  ...(total " + sel.rowCount + " rows)\n";
    } else {
      info += "- One cell selected: " + selAddr + "\n";

      const used = sheet.getUsedRangeOrNullObject();
      used.load("address, values, rowCount, columnCount");
      await ctx.sync();

      if (!used.isNullObject) {
        info += "- Used range: " + used.address + " (" + used.rowCount + " rows x " + used.columnCount + " columns)\n";

        const preview = used.values
          .slice(0, 20)
          .map((r, i) => "  row " + i + ": [" + r.join(" | ") + "]")
          .join("\n");

        info += "- Preview:\n" + preview + "\n";
      }
    }
  });

  return info;
}

async function runExcelCode(code) {
  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const workbook = context.workbook;

    const sel = workbook.getSelectedRange();
    sel.load("values, rowCount, columnCount, address, columnIndex, rowIndex");

    await context.sync();

    const selData = sel.values;
    const selInfo = {
      address: sel.address,
      rowCount: sel.rowCount,
      colCount: sel.columnCount,
      startCol: sel.columnIndex,
      startRow: sel.rowIndex
    };

    const runner = new Function(
      "context",
      "sheet",
      "workbook",
      "Excel",
      "selData",
      "selInfo",
      "return (async () => { " + code + "\nawait context.sync(); })();"
    );

    await runner(context, sheet, workbook, Excel, selData, selInfo);
    await context.sync();
  });
}

async function getWordContext() {
  let info = "";

  await Word.run(async (ctx) => {
    const sel = ctx.document.getSelection();
    sel.load("text");
    await ctx.sync();
    info += '- Selected text: "' + (sel.text || "(none)") + '"\n';
  });

  return info;
}

async function runWordCode(code) {
  await Word.run(async (context) => {
    const doc = context.document;
    const selection = context.document.getSelection();
    const body = context.document.body;

    const runner = new Function(
      "context",
      "doc",
      "selection",
      "body",
      "Word",
      "return (async () => { " + code + "\nawait context.sync(); })();"
    );

    await runner(context, doc, selection, body, Word);
    await context.sync();
  });
}

const EXCEL_RULES = `
You are an Office.js expert for Excel.

Return only plain JavaScript code.
No markdown.
No backticks.
No explanation.

The code runs inside:
await Excel.run(async (context) => {
  <CODE>
  await context.sync();
});

Available variables:
context, sheet, workbook, Excel, selData, selInfo.

Important rules:
1. If context says SELECTED RANGE, use selData to read data.
2. Do not use getUsedRange or getSelectedRange to read data when selData is available.
3. Use workbook.getSelectedRange() only for formatting the selected range.
4. selData is a 2D array. Usually selData[0] is header, data starts from selData[1].
5. Write value: sheet.getRange("D3").values = [[x]];
6. Write formula: sheet.getRange("D3").formulas = [["=SUM(A:A)"]];
7. Write dynamic array: sheet.getRange("P33").getResizedRange(n - 1, m - 1).values = arr;
8. numberFormat must have correct 2D size.
9. Do not invent base64 images.
`;

const WORD_RULES = `
You are an Office.js expert for Word.

Return only plain JavaScript code.
No markdown.
No backticks.
No explanation.

The code runs inside:
await Word.run(async (context) => {
  <CODE>
  await context.sync();
});

Available variables:
context, doc, selection, body, Word.

Common API:
selection.insertText("content", Word.InsertLocation.replace);
body.insertParagraph("content", Word.InsertLocation.end);
selection.font.name = "Times New Roman";
selection.font.size = 13;
`;

async function executeCommand() {
  const input = document.getElementById("prompt_input");
  const btn = document.getElementById("run_button");
  const userPrompt = input ? input.value.trim() : "";

  if (!userPrompt) {
    showStatus("Please enter a request.", "error");
    return;
  }

  saveSettings();
  if (btn) btn.disabled = true;

  try {
    const gb = parseGroupByCommand(userPrompt);

    if (gb && HOST_APP === "Excel") {
      await runGroupBy(gb.groupCols, gb.sumCol, gb.targetCell, gb.formulaMode);
      return;
    }

    showStatus("Understanding request...", "loading");

    const intent = await classifyIntent(userPrompt);

    if (intent === "CHAT") {
      showStatus("Answering...", "loading");
      await handleChat(userPrompt);
      return;
    }

    let contextInfo = "";
    let rules = "";
    let runFunc = null;

    if (HOST_APP === "Excel") {
      contextInfo = await getExcelContext();
      rules = EXCEL_RULES;
      runFunc = runExcelCode;
    } else if (HOST_APP === "Word") {
      contextInfo = await getWordContext();
      rules = WORD_RULES;
      runFunc = runWordCode;
    } else {
      throw new Error("Only Excel and Word are supported.");
    }

    let lastError = "";
    let code = "";

    for (let attempt = 1; attempt <= MAX_RETRY; attempt++) {
      showStatus(
        attempt === 1 ? "Writing code..." : "Retrying " + attempt + "/" + MAX_RETRY + "...",
        "loading"
      );

      const prompt =
        attempt === 1
          ? rules + "\n\nCONTEXT:\n" + contextInfo + "\n\nREQUEST:\n" + userPrompt + "\n\nReturn only code:"
          : rules + "\n\nCONTEXT:\n" + contextInfo + "\n\nREQUEST:\n" + userPrompt + "\n\nBAD CODE:\n" + code + "\n\nERROR:\n" + lastError + "\n\nReturn fixed code only:";

      code = cleanCode(
        await callAI(prompt, {
          temperature: 0.1,
          maxTokens: 8192,
          system: "You are an Office.js expert. Return only plain JavaScript code."
        })
      );

      console.log("Attempt " + attempt + " code:\n" + code);

      try {
        await runFunc(code);
        showStatus(attempt === 1 ? "OK: Done." : "OK: Done after retry " + attempt + ".", "success");
        return;
      } catch (e) {
        lastError = e.message;
        console.warn("Attempt " + attempt + " failed:", lastError);

        if (attempt === MAX_RETRY) {
          throw new Error("Failed after " + MAX_RETRY + " retries: " + lastError);
        }
      }
    }
  } catch (e) {
    console.error(e);
    showStatus("ERROR: " + e.message, "error");
  } finally {
    if (btn) btn.disabled = false;
  }
}

function clearAll() {
  const input = document.getElementById("prompt_input");
  const status = document.getElementById("status_area");

  if (input) input.value = "";
  if (status) {
    status.className = "status";
    status.innerText = "";
  }
}